style.css:
@-moz-document domain("roblox.com") {
/* General page background & font */
  body, .container-main {
    background-color: #f5f5f5 !important;
    font-family: "Arial", sans-serif !important;
    color: #333 !important;
  }

  /* Header - classic blue */
  #header, .navigation, .top-nav {
    background-color: #0055cc !important;
    border-bottom: 2px solid #003d99 !important;
  }

  /* Catalog / Items */
  .item-card, .game-card {
    border: 1px solid #ccc !important;
    box-shadow: none !important;
    background-color: white !important;
  }

  /* Old style buttons */
  button, .btn-primary, .btn-secondary {
    background-color: #0055cc !important;
    color: white !important;
    border-radius: 2px !important;
    border: none !important;
  }

  /* Sidebar and menus */
  .sidebar, .nav-menu {
    background-color: #e0e0e0 !important;
    border-right: 1px solid #ccc !important;
  }

  /* Avatar wardrobe page */
  #avatar-wearables, #avatar-editor {
    background-color: white !important;
    border: 1px solid #ccc !important;
    padding: 10px !important;
  }

  /* Profile info block */
  .profile-header, .profile-stats {
    background-color: #e6f0ff !important;
    border: 1px solid #99bbff !important;
  }

  /* Links color */
  a {
    color: #003d99 !important;
  }

  /* Remove rounded corners */
  * {
    border-radius: 0 !important;
  }

  /* Smaller font for catalog descriptions */
  .item-description, .game-description {
    font-size: 12px !important;
  }
}
